import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./dashboard.css";

export default function Dashboard() {
  const navigate = useNavigate();

  const user = JSON.parse(localStorage.getItem("user"));

  const [users, setUsers] = useState(JSON.parse(localStorage.getItem("users")) || []);
  const [courses, setCourses] = useState(JSON.parse(localStorage.getItem("courses")) || []);

  if (!user) {
    navigate("/login");
    return null;
  }

  const deleteUser = (id) => {
    const updated = users.filter(u => u.id !== id);
    setUsers(updated);
    localStorage.setItem("users", JSON.stringify(updated));
  };

  const deleteCourse = (id) => {
    const updated = courses.filter(c => c.id !== id);
    setCourses(updated);
    localStorage.setItem("courses", JSON.stringify(updated));
  };

  const logout = () => {
    localStorage.removeItem("user");
    navigate("/login");
  };

  return (
    <div className="dashboard-container">

      {/* HEADER */}
      <div className="header">
        <h1>🎯 Admin Dashboard</h1>
        <h2>Welcome {user.name}</h2>
        <p>{user.email}</p>

        <button className="logout-btn" onClick={logout}>
          Logout
        </button>
      </div>

      {/* STATS */}
      <div className="stats">
        <div className="stat">
          <h3>Total Users</h3>
          <p>{users.length}</p>
        </div>

        <div className="stat">
          <h3>Students</h3>
          <p>{users.filter(u => u.role === "Student").length}</p>
        </div>

        <div className="stat">
          <h3>Instructors</h3>
          <p>{users.filter(u => u.role === "Instructor").length}</p>
        </div>

        <div className="stat">
          <h3>Courses</h3>
          <p>{courses.length}</p>
        </div>
      </div>

      {/* USERS LIST */}
      <h2 className="section-title">👥 Users List</h2>

      <div className="table">
        {users.map(u => (
          <div className="row" key={u.id}>
            <span>{u.name}</span>
            <span>{u.email}</span>
            <span>{u.role}</span>

            <button onClick={() => deleteUser(u.id)}>Delete</button>
          </div>
        ))}
      </div>

      {/* COURSES LIST */}
      <h2 className="section-title">📚 Courses List</h2>

      <div className="table">
        {courses.map(c => (
          <div className="row" key={c.id}>
            <span>{c.name}</span>
            <span>{c.instructor}</span>

            <button onClick={() => deleteCourse(c.id)}>Delete</button>
          </div>
        ))}
      </div>

    </div>
  );
}
